 const [user,setUser]=useState<any>(null),[authOpen,setAuthOpen]=useState(false),[page,setPage]=useState<"home"|"map"|"learn"|"lesson"|"practice"|"quests"|"skills"|"playground"|"workshop"|"guild">("home"),[selected,setSelected]=useState(lessons[0].slug),[done,setDone]=useState<string[]>([]),[answer,setAnswer]=useState<number|null>(null),[checked,setChecked]=useState(false),[email,setEmail]=useState(""),[authBusy,setAuthBusy]=useState(false),[notice,setNotice]=useState(""),[search,setSearch]=useState(""),[player,setPlayer]=useState<Player>({total_xp:0,level:1,current_streak:0,longest_streak:0}),[quests,setQuests]=useState<Quest[]>([]),[unlocked,setUnlocked]=useState<string[]>([]),[busy,setBusy]=useState(false),[code,setCode]=useState(starterCode),[runState,setRunState]=useState<"idle"|"loading"|"running"|"done"|"error">("idle"),[output,setOutput]=useState<{kind:string;text:string}[]>([]),[mobileNav,setMobileNav]=useState(false),[projects,setProjects]=useState<LearnerProject[]>([]),[projectTitle,setProjectTitle]=useState("My first Python project"),[projectDescription,setProjectDescription]=useState("A small program I built in Python Odyssey."),[projectCode,setProjectCode]=useState(starterCode),[mentorQuestion,setMentorQuestion]=useState("I keep getting confused by loops. How do I practice?"),[mentorReplyText,setMentorReplyText]=useState(""),[mentorLoading,setMentorLoading]=useState(false),[dailyChallenge,setDailyChallenge]=useState<DailyChallenge|null>(null),[challengeAnswer,setChallengeAnswer]=useState(""),[challengeResult,setChallengeResult]=useState<any>(null),[leaderboard,setLeaderboard]=useState<RankRow[]>([]),[practiceIndex,setPracticeIndex]=useState(()=>Math.floor(Math.random()*lessons.length)),[practiceAnswer,setPracticeAnswer]=useState<number|null>(null),[practiceChecked,setPracticeChecked]=useState(false);
 const workerRef=useRef<Worker|null>(null),timerRef=useRef<number|undefined>(undefined);
 const lesson=lessons.find(x=>x.slug===selected)!,percent=Math.round(done.length/lessons.length*100),filtered=useMemo(()=>lessons.filter(l=>(l.title+" "+l.summary+" "+l.world).toLowerCase().includes(search.toLowerCase())),[search]);
 const refresh=useCallback(async(uid:string)=>{
  if(!supabase)return;
  const settled=await Promise.allSettled([
   withTimeout(supabase.from("lesson_progress").select("lesson_slug,completed").eq("user_id",uid)),
   withTimeout(supabase.from("player_stats").select("total_xp,level,current_streak,longest_streak").eq("user_id",uid).maybeSingle()),
   withTimeout(supabase.from("quest_catalog").select("slug,title,description,goal_type,goal_value,xp_reward,world_name").eq("active",true)),
   withTimeout(supabase.from("user_achievements").select("achievement_slug").eq("user_id",uid))
  ]);
  const value=(i:number)=>settled[i].status==="fulfilled"?settled[i].value:null;
  const progress:any=value(0),stats:any=value(1),questRows:any=value(2),achRows:any=value(3);
  if(progress?.data)setDone(progress.data.filter((x:any)=>x.completed).map((x:any)=>x.lesson_slug));
  if(stats?.data)setPlayer(stats.data);
  if(achRows?.data)setUnlocked(achRows.data.map((x:any)=>x.achievement_slug));
  if(questRows?.data){
   const [p,ledger]=await Promise.allSettled([
    withTimeout(supabase.from("quest_progress").select("quest_slug,progress_value,completed_at").eq("user_id",uid)),
    withTimeout(supabase.from("xp_ledger").select("source_key").eq("user_id",uid).like("source_key","quest:%"))
   ]);
   const pData=p.status==="fulfilled"?p.value.data||[]:[];
   const ledgerData=ledger.status==="fulfilled"?ledger.value.data||[]:[];
   const claimed=new Set(ledgerData.map((x:any)=>x.source_key.slice(6)));
   const pm=new Map(pData.map((x:any)=>[x.quest_slug,x]));
   setQuests(questRows.data.map((q:any)=>({...q,...pm.get(q.slug),claimed:claimed.has(q.slug)})));
  }
  const [daily,rank,saved]=await Promise.allSettled([
   withTimeout(supabase.rpc("get_daily_challenge")),
   withTimeout(supabase.rpc("get_public_leaderboard",{p_limit:20})),
   withTimeout(supabase.from("learner_projects").select("id,title,description,code,created_at").eq("user_id",uid).order("created_at",{ascending:false}).limit(20))
  ]);
  if(daily.status==="fulfilled"&&daily.value.data?.[0])setDailyChallenge(daily.value.data[0] as DailyChallenge);
  if(rank.status==="fulfilled"&&rank.value.data)setLeaderboard(rank.value.data as RankRow[]);
  if(saved.status==="fulfilled"&&saved.value.data)setProjects(saved.value.data as LearnerProject[]);
 },[]);
 useEffect(()=>{if(page!=="playground"&&workerRef.current){workerRef.current.terminate();workerRef.current=null;if(timerRef.current)window.clearTimeout(timerRef.current);setRunState("idle")}},[page]);
 useEffect(()=>{if(!supabase)return;let active=true;withTimeout(supabase.auth.getSession(),8000).then(({data,error})=>{if(!active)return;if(error)console.warn("Auth session check failed:",error.message);const current=data.session?.user??null;setUser(current);if(current){setAuthOpen(false);void refresh(current.id).catch(err=>console.warn("Player data could not be loaded:",err));}}).catch(err=>console.warn("Auth initialization failed:",err));const {data}=supabase.auth.onAuthStateChange((_e,s)=>{if(!active)return;const current=s?.user??null;setUser(current);if(current){setAuthOpen(false);void refresh(current.id).catch(err=>console.warn("Player data refresh failed:",err));}else{setDone([]);setPlayer({total_xp:0,level:1,current_streak:0,longest_streak:0});setQuests([]);setUnlocked([]);setProjects([])}});return()=>{active=false;data.subscription.unsubscribe();workerRef.current?.terminate();if(timerRef.current)window.clearTimeout(timerRef.current)}},[refresh]);
 const notify=(message:string)=>{setNotice(message);window.setTimeout(()=>setNotice(""),4200)};
 async function signIn(e:FormEvent){e.preventDefault();if(!supabase){notify("Sign-in is not configured. Check the Supabase URL and publishable key in the frontend deployment.");return}if(!email.trim()){notify("Enter your email address first.");return}setAuthBusy(true);try{const {error}=await supabase.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:AUTH_REDIRECT_URL}});if(error)notify(error.message);else notify("Magic link sent! Open the newest email and tap the link. It will return to Python Odyssey.");}catch{notify("Could not send the sign-in link. Please try again.")}finally{setAuthBusy(false)}}
 function openLesson(slug:string){setSelected(slug);setAnswer(null);setChecked(false);setPage("lesson");setMobileNav(false);window.scrollTo(0,0)}
 async function submitAnswer(){if(answer===null)return;if(!user||!supabase){setChecked(true);if(answer===lesson.answer)notify("Correct! Sign in to save XP and quest progress.");return}setBusy(true);const {data,error}=await supabase.rpc("submit_lesson_answer",{p_lesson_slug:lesson.slug,p_answer_index:answer});setChecked(true);if(error)notify("Could not save your answer: "+error.message);else if(data?.correct){await refresh(user.id);notify(data.xp_gained>0?"Correct! +"+data.xp_gained+" XP earned.":"Correct! You already claimed this lesson's XP.");}else notify("Not quite. Review the lesson and try again.");setBusy(false)}
 async function claimQuest(q:Quest){if(!user||!supabase)return;setBusy(true);const {data,error}=await supabase.rpc("claim_quest_reward",{p_quest_slug:q.slug});if(error)notify(error.message);else{notify("Quest reward claimed: +"+data.xp_gained+" XP!");await refresh(user.id)}setBusy(false)}
 async function saveProject(){if(!user||!supabase){notify("Sign in to save projects to your portfolio.");return}if(!projectTitle.trim()||!projectCode.trim()){notify("Add a project title and some code first.");return}setBusy(true);const {data,error}=await supabase.from("learner_projects").insert({user_id:user.id,title:projectTitle.trim().slice(0,80),description:projectDescription.trim().slice(0,300),code:projectCode.slice(0,12000)}).select("id,title,description,code,created_at").single();if(error)notify("Project could not be saved: "+error.message);else{setProjects(old=>[data as LearnerProject,...old]);notify("Project saved to your adventurer portfolio.")}setBusy(false)}
 async function mentorReply(){if(!user||!supabase){notify("Sign in to ask the Sage.");return}setMentorLoading(true);setMentorReplyText("");try{const {data}=await supabase.auth.getSession();const token=data.session?.access_token;if(!token)throw new Error("Please sign in again.");const api=import.meta.env.VITE_API_URL||"https://python-odyssey-api-v2.onrender.com";const response=await fetch(api+"/api/v1/mentor",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({question:mentorQuestion,completed_lessons:done})});const result=await response.json();if(!response.ok)throw new Error(result.detail||"The Sage is unavailable.");setMentorReplyText(result.reply||"The Sage has no answer right now.");}catch(e){mentorReplyFallback();notify("The Sage connection failed, so I showed an offline study hint instead.");}finally{setMentorLoading(false)}}
 function mentorReplyFallback(){const q=mentorQuestion.toLowerCase();let reply="Break the problem into the smallest possible steps. Write one tiny example, predict its output, run it in the Code Lab, then change one thing at a time.";if(q.includes("loop")||q.includes("while")||q.includes("for"))reply="Think of a loop as a repeatable quest. Use for when you know the sequence you want to visit (for item in items). Use while when you repeat until a condition changes. Always make sure a while loop can eventually become false. Try range(1, 4) and print each number.";else if(q.includes("function")||q.includes("return"))reply="A function is a reusable tool. Start with def name(parameters):, indent its steps, and use return when you want to send a result back. Try writing a function that accepts two numbers and returns their sum.";else if(q.includes("error")||q.includes("bug")||q.includes("debug"))reply="Read the last line of the traceback first; it usually names the error. Check the line number, spelling, quotes, brackets, and indentation. Reduce the code to the smallest example that still fails, then test again.";else if(q.includes("list")||q.includes("dictionary")||q.includes("data"))reply="Use a list for an ordered collection, and a dictionary for key-value pairs. Practice by making an inventory list, appending an item, then looping over it. For dictionaries, try player = {'name': 'Nova', 'level': 1}.";else if(q.includes("start")||q.includes("beginner"))reply="Start with print(), variables, strings, and numbers. Change the starter code in the Code Lab and predict what each print() will show. Short experiments build confidence faster than memorizing syntax.";setMentorReplyText(reply)}
 async function submitChallenge(){if(!user||!supabase||!dailyChallenge){notify("Sign in to attempt the daily challenge.");return}setBusy(true);const {data,error}=await supabase.rpc("submit_daily_challenge",{p_slug:dailyChallenge.slug,p_answer:challengeAnswer});if(error)notify(error.message);else{setChallengeResult(data);if(data.correct){notify("Daily challenge cleared! +"+data.xp_gained+" XP");await refresh(user.id)}else notify(data.already_submitted?"You already attempted today’s challenge.":"Not quite. Review the hint and try again tomorrow.");}setBusy(false)}
 function exportPortfolio(){const data={title:"Python Odyssey Adventurer Portfolio",player:{email:user?.email||"Guest",level:player.level,totalXP:player.total_xp,streak:player.current_streak},completedLessons:done,achievements:unlocked,projects:projects.map(p=>({title:p.title,description:p.description,createdAt:p.created_at,code:p.code}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="python-odyssey-portfolio.json";a.click();URL.revokeObjectURL(url);notify("Portfolio export prepared.")}
 function runPython(){if(runState==="loading"||runState==="running")return;workerRef.current?.terminate();const blob=new Blob([workerSource],{type:"text/javascript"}),url=URL.createObjectURL(blob),worker=new Worker(url);workerRef.current=worker;setOutput([{kind:"system",text:"Booting Python runtime…"}]);setRunState("loading");timerRef.current=window.setTimeout(()=>{worker.terminate();workerRef.current=null;setRunState("error");setOutput(old=>[...old,{kind:"error",text:"Execution stopped after 15 seconds. Check for an infinite loop."}])},15000);let workerUrlReleased=false;const releaseWorkerUrl=()=>{if(!workerUrlReleased){URL.revokeObjectURL(url);workerUrlReleased=true}};worker.onmessage=(event)=>{releaseWorkerUrl();const m=event.data;if(m.type==="stdout"||m.type==="stderr"){setRunState("running");setOutput(old=>[...old.filter(x=>x.kind!=="system"),{kind:m.type,text:m.text}])}else if(m.type==="done"){if(timerRef.current)window.clearTimeout(timerRef.current);setRunState("done");setOutput(old=>old.length?old:[{kind:"system",text:"Program finished with no output."}])}else if(m.type==="error"){if(timerRef.current)window.clearTimeout(timerRef.current);setRunState("error");setOutput(old=>[...old,{kind:"error",text:m.text}])}};worker.onerror=(event)=>{releaseWorkerUrl();if(timerRef.current)window.clearTimeout(timerRef.current);setRunState("error");setOutput(old=>[...old,{kind:"error",text:event.message||"Python worker failed."}])};worker.postMessage({code})}
 const nav=[{id:"home",label:"Camp",icon:Home},{id:"map",label:"World map",icon:MapIcon},{id:"learn",label:"Lessons",icon:BookOpen},{id:"practice",label:"Practice arena",icon:Activity},{id:"quests",label:"Quest board",icon:Award},{id:"skills",label:"Skill tree",icon:Gem},{id:"playground",label:"Code lab",icon:Terminal},{id:"workshop",label:"Workshop",icon:FolderGit2},{id:"guild",label:"Guild",icon:Trophy}] as const;
